    _vocab("Group 9", 14, "Speculate", "Verb", "To guess about something without having all the facts.", "সব তথ্য না জেনে অনুমান করা", "People speculate about the result.", "মানুষ ফলাফল নিয়ে অনুমান করে।"),
    _vocab("Group 9", 15, "Enrapture", "Verb", "To fill someone with great joy or delight.", "কাউকে গভীর আনন্দে মুগ্ধ করা", "The music can enrapture the audience.", "সঙ্গীতটি শ্রোতাদের মুগ্ধ করতে পারে।"),
    _vocab("Group 9", 16, "Sophisticated", "Adjective", "Advanced, complex, or highly developed.", "উন্নত, জটিল বা অত্যন্ত বিকশিত", "This is a sophisticated machine.", "এটি একটি উন্নত যন্ত্র।"),
    _vocab("Group 9", 17, "Laud", "Verb", "To praise someone or something highly.", "কাউকে বা কিছুকে খুব প্রশংসা করা", "People laud her brave work.", "মানুষ তার সাহসী কাজের প্রশংসা করে।"),
    _vocab("Group 9", 18, "Revere", "Verb", "To respect and admire someone deeply.", "কাউকে গভীরভাবে সম্মান ও শ্রদ্ধা করা", "Many people revere the old teacher.", "অনেক মানুষ বৃদ্ধ শিক্ষককে গভীরভাবে শ্রদ্ধা করে।"),
    _vocab("Group 9", 19, "Pseudoscience", "Noun", "Ideas that claim to be scientific but do not use proper scientific methods.", "বৈজ্ঞানিক বলে দাবি করা হলেও সঠিক বৈজ্ঞানিক পদ্ধতি ব্যবহার করে না এমন ধারণা", "The book warns us about pseudoscience.", "বইটি আমাদের ছদ্মবিজ্ঞান সম্পর্কে সতর্ক করে।"),
    _vocab("Group 9", 20, "Condemn", "Verb", "To strongly say that something is wrong or unacceptable.", "কোনো কিছুকে কঠোরভাবে ভুল বা অগ্রহণযোগ্য বলা", "People condemn the cruel act.", "মানুষ নিষ্ঠুর কাজটির নিন্দা করে।"),
    _vocab("Group 10", 1, "Recoil", "Verb / Noun", "To move back suddenly because of fear, shock, or pain.", "ভয়, বিস্ময় বা ব্যথায় হঠাৎ পিছিয়ে যাওয়া", "She recoiled from the hot pan.", "সে গরম পাত্রটি থেকে হঠাৎ পিছিয়ে গেল।"),
    _vocab("Group 10", 2, "Essence", "Noun", "The most important quality or basic nature of something.", "কোনো কিছুর সবচেয়ে গুরুত্বপূর্ণ গুণ বা মূল স্বভাব", "Kindness is the essence of friendship.", "দয়া হলো বন্ধুত্বের মূল কথা।"),
    _vocab("Group 10", 3, "Speculation", "Noun", "A guess or discussion without complete facts.", "সম্পূর্ণ তথ্য ছাড়া অনুমান বা আলোচনা", "There is much speculation about the plan.", "পরিকল্পনাটি নিয়ে অনেক অনুমান আছে।"),
    _vocab("Group 10", 4, "Anoint", "Verb", "To put oil or another substance on a person in a religious ceremony.", "ধর্মীয় অনুষ্ঠানে কারও শরীরে তেল বা অন্য পদার্থ লাগানো", "The priest will anoint the man's head.", "পুরোহিত লোকটির মাথায় তেল লাগাবেন।"),
    _vocab("Group 10", 5, "Condiment", "Noun", "A sauce or seasoning added to food for extra flavour.", "খাবারে অতিরিক্ত স্বাদ যোগ করার সস বা মসলা", "Salt is a common condiment.", "লবণ একটি সাধারণ স্বাদবর্ধক।"),
    _vocab("Group 10", 6, "Indigestion", "Noun", "Pain or discomfort in the stomach after eating.", "খাওয়ার পর পেটে ব্যথা বা অস্বস্তি", "Too much food can cause indigestion.", "অতিরিক্ত খাবার বদহজম ঘটাতে পারে।"),
    _vocab("Group 10", 7, "Exorbitantly", "Adverb", "At an unreasonably high price or amount.", "অযৌক্তিকভাবে বেশি দাম বা পরিমাণে", "The hotel charges exorbitantly high prices.", "হোটেলটি অযৌক্তিকভাবে বেশি দাম নেয়।"),
    _vocab("Group 10", 8, "Spur", "Verb / Noun", "To encourage or cause someone to act.", "কাউকে কাজ করতে উৎসাহিত বা তাড়িত করা", "The prize can spur students to work.", "পুরস্কার শিক্ষার্থীদের কাজ করতে উৎসাহিত করতে পারে।"),
    _vocab("Group 10", 9, "Pliable", "Adjective", "Easy to bend, shape, or influence.", "সহজে বাঁকানো, আকার দেওয়া বা প্রভাবিত করা যায় এমন", "The soft clay is pliable.", "নরম মাটি সহজে আকার দেওয়া যায়।"),
    _vocab("Group 10", 10, "Enslave", "Verb", "To make someone a slave or control them completely.", "কাউকে দাস বানানো বা সম্পূর্ণভাবে নিয়ন্ত্রণ করা", "No one has the right to enslave another person.", "কাউকে দাস বানানোর অধিকার কারও নেই।"),
    _vocab("Group 10", 11, "Overrun", "Verb / Noun", "To spread over or take control of a place in large numbers.", "বিপুল সংখ্যায় কোনো স্থান ছেয়ে ফেলা বা দখল করা", "Weeds can overrun the garden.", "আগাছা বাগানটি ছেয়ে ফেলতে পারে।"),
    _vocab("Group 10", 12, "Lucrative", "Adjective", "Producing a large amount of money or profit.", "অনেক অর্থ বা লাভ এনে দেয় এমন", "The business is very lucrative.", "ব্যবসাটি খুব লাভজনক।"),
    _vocab("Group 10", 13, "Diminish", "Verb", "To become or make something smaller or less important.", "ছোট, কম বা কম গুরুত্বপূর্ণ হওয়া বা করা", "The pain will diminish soon.", "ব্যথা শিগগিরই কমে যাবে।"),
    _vocab("Group 10", 14, "Supersede", "Verb", "To replace something older or less effective.", "পুরোনো বা কম কার্যকর কিছুকে প্রতিস্থাপন করা", "New phones often supersede old models.", "নতুন ফোন প্রায়ই পুরোনো মডেলকে প্রতিস্থাপন করে।"),
    _vocab("Group 10", 15, "Adept", "Adjective", "Very skilled at doing something.", "কোনো কিছু করতে খুব দক্ষ", "She is adept at drawing.", "সে আঁকায় খুব দক্ষ।"),
    _vocab("Group 10", 16, "Propel", "Verb", "To push or move something forward.", "কোনো কিছুকে সামনে ঠেলা বা চালিত করা", "The motor propels the boat.", "মোটরটি নৌকাকে সামনে চালায়।"),
    _vocab("Group 10", 17, "Attuned", "Adjective", "Able to understand or notice something well.", "কোনো কিছু ভালোভাবে বুঝতে বা লক্ষ্য করতে সক্ষম", "She is attuned to her baby's needs.", "সে তার শিশুর প্রয়োজন ভালোভাবে বোঝে।"),
    _vocab("Group 10", 18, "Perplexing", "Adjective", "Difficult to understand; confusing.", "বোঝা কঠিন; বিভ্রান্তিকর", "This question is perplexing.", "এই প্রশ্নটি বিভ্রান্তিকর।"),
    _vocab("Group 10", 19, "Manifest", "Verb / Adjective", "To show something clearly; clear and obvious.", "কোনো কিছু স্পষ্টভাবে দেখানো; স্পষ্ট ও প্রকাশ্য", "His fear began to manifest.", "তার ভয় প্রকাশ পেতে শুরু করল।"),
    _vocab("Group 10", 20, "Profound", "Adjective", "Very deep, serious, or important.", "অত্যন্ত গভীর, গুরুতর বা গুরুত্বপূর্ণ", "The book had a profound effect on me.", "বইটি আমার ওপর গভীর প্রভাব ফেলেছিল।"),
    _vocab("Group 11", 1, "Peripheral", "Adjective / Noun", "Related to the outer edge or less important part of something.", "কোনো কিছুর বাইরের প্রান্ত বা কম গুরুত্বপূর্ণ অংশ-সংক্রান্ত", "I saw the light with my peripheral vision.", "আমি চোখের পাশের দৃষ্টি দিয়ে আলোটি দেখেছি।"),
    _vocab("Group 11", 2, "Jeopardize", "Verb", "To put someone or something in danger.", "কাউকে বা কিছুকে বিপদের মধ্যে ফেলা", "Do not jeopardize your health.", "তোমার স্বাস্থ্যকে ঝুঁকির মধ্যে ফেলো না।"),
    _vocab("Group 11", 3, "Proposition", "Noun", "An idea, plan, or offer for people to consider.", "বিবেচনার জন্য দেওয়া ধারণা, পরিকল্পনা বা প্রস্তাব", "She made a simple proposition.", "সে একটি সহজ প্রস্তাব দিল।"),
    _vocab("Group 11", 4, "Infuse", "Verb", "To fill something with a quality, feeling, or substance.", "কোনো কিছুকে গুণ, অনুভূতি বা পদার্থ দিয়ে পূর্ণ করা", "The teacher can infuse the class with energy.", "শিক্ষক শ্রেণিকক্ষে প্রাণশক্তি আনতে পারেন।"),
    _vocab("Group 11", 5, "Augment", "Verb", "To increase the size, amount, or value of something.", "কোনো কিছুর আকার, পরিমাণ বা মূল্য বাড়ানো", "We need to augment our food supply.", "আমাদের খাদ্য সরবরাহ বাড়াতে হবে।"),
    _vocab("Group 11", 6, "Unleash", "Verb", "To release a strong force, feeling, or action.", "শক্তিশালী বল, অনুভূতি বা কাজ মুক্ত করে দেওয়া", "The storm may unleash heavy rain.", "ঝড়টি ভারী বৃষ্টি নামাতে পারে।"),
    _vocab("Group 11", 7, "Opulence", "Noun", "Great wealth and luxurious comfort.", "অত্যধিক সম্পদ ও বিলাসিতা", "The palace showed great opulence.", "প্রাসাদটি বিপুল বিলাসিতা দেখায়।"),
    _vocab("Group 11", 8, "Avert", "Verb", "To prevent something bad from happening.", "খারাপ কিছু ঘটতে বাধা দেওয়া", "Quick action can avert danger.", "দ্রুত পদক্ষেপ বিপদ ঠেকাতে পারে।"),
    _vocab("Group 11", 9, "Accumulate", "Verb", "To collect or increase gradually over time.", "সময়ের সঙ্গে ধীরে ধীরে জমা করা বা বাড়া", "Dust can accumulate on the table.", "টেবিলে ধুলো জমতে পারে।"),
    _vocab("Group 11", 10, "Redeem", "Verb", "To make something better or regain value, respect, or freedom.", "কোনো কিছু ভালো করা বা মূল্য, সম্মান বা স্বাধীনতা ফিরে পাওয়া", "He worked hard to redeem himself.", "সে নিজেকে শুধরাতে কঠোর পরিশ্রম করল।"),
    _vocab("Group 11", 11, "Transcend", "Verb", "To go beyond a normal limit or level.", "স্বাভাবিক সীমা বা স্তর অতিক্রম করা", "True friendship can transcend distance.", "সত্যিকারের বন্ধুত্ব দূরত্ব অতিক্রম করতে পারে।"),
    _vocab("Group 11", 12, "Apparel", "Noun", "Clothing, especially when sold in shops.", "পোশাক, বিশেষ করে দোকানে বিক্রি করা পোশাক", "The shop sells children's apparel.", "দোকানটি শিশুদের পোশাক বিক্রি করে।"),
    _vocab("Group 11", 13, "Reaffirm", "Verb", "To state or show again that something is true or important.", "কোনো কিছু সত্য বা গুরুত্বপূর্ণ বলে আবার নিশ্চিত করা", "She will reaffirm her promise.", "সে তার প্রতিশ্রুতি আবার নিশ্চিত করবে।"),
    _vocab("Group 11", 14, "Reinvigorate", "Verb", "To give new energy or strength to someone or something.", "কাউকে বা কিছুকে নতুন শক্তি বা প্রাণশক্তি দেওয়া", "A short rest can reinvigorate you.", "অল্প বিশ্রাম তোমাকে নতুন শক্তি দিতে পারে।"),
    _vocab("Group 11", 15, "Counteract", "Verb", "To reduce or prevent the effect of something harmful.", "ক্ষতিকর কিছুর প্রভাব কমানো বা প্রতিরোধ করা", "This medicine can counteract the poison.", "এই ওষুধ বিষের প্রভাব কমাতে পারে।"),
    _vocab("Group 11", 16, "Envisage", "Verb", "To imagine or picture something that may happen.", "ঘটতে পারে এমন কিছু কল্পনা করা", "I envisage a better future.", "আমি একটি ভালো ভবিষ্যৎ কল্পনা করি।"),
    _vocab("Group 11", 17, "Surmount", "Verb", "To successfully deal with or overcome a difficulty.", "কোনো অসুবিধা সফলভাবে মোকাবিলা বা অতিক্রম করা", "We can surmount this problem together.", "আমরা একসঙ্গে এই সমস্যা অতিক্রম করতে পারি।"),
    _vocab("Group 11", 18, "Fibrous", "Adjective", "Made of or containing many thin fibres.", "অনেক সরু আঁশ দিয়ে তৈরি বা আঁশযুক্ত", "The plant has fibrous roots.", "গাছটির আঁশযুক্ত শিকড় আছে।"),
    _vocab("Group 11", 19, "Solidify", "Verb", "To become or make something solid; to make stronger or more certain.", "কঠিন হওয়া বা করা; আরও শক্ত বা নিশ্চিত করা", "The liquid will solidify in the cold.", "ঠান্ডায় তরলটি জমে কঠিন হবে।"),
    _vocab("Group 11", 20, "Viable", "Adjective", "Able to work successfully or continue to live.", "সফলভাবে কাজ করতে বা বেঁচে থাকতে সক্ষম", "This is a viable plan.", "এটি একটি কার্যকর পরিকল্পনা।"),
    _vocab("Group 12", 1, "Germinate", "Verb", "To begin to grow from a seed.", "বীজ থেকে অঙ্কুরিত হওয়া", "The seeds will germinate in warm soil.", "উষ্ণ মাটিতে বীজগুলো অঙ্কুরিত হবে।"),
    _vocab("Group 12", 2, "Indigenous", "Adjective", "Naturally belonging to a particular place.", "কোনো নির্দিষ্ট স্থানের স্থানীয় বা স্বাভাবিকভাবে জন্মানো", "This plant is indigenous to the island.", "এই গাছটি দ্বীপটির স্থানীয়।"),
    _vocab("Group 12", 3, "Disperse", "Verb", "To spread in different directions.", "বিভিন্ন দিকে ছড়িয়ে পড়া বা ছড়িয়ে দেওয়া", "The wind can disperse the smoke.", "বাতাস ধোঁয়াটি ছড়িয়ে দিতে পারে।"),
    _vocab("Group 12", 4, "Babble", "Verb / Noun", "To talk quickly in a way that is difficult to understand.", "দ্রুত ও অস্পষ্টভাবে কথা বলা", "The baby began to babble.", "শিশুটি অস্পষ্টভাবে কথা বলতে শুরু করল।"),
    _vocab("Group 12", 5, "Synthesize", "Verb", "To combine different ideas or materials into a new whole.", "বিভিন্ন ধারণা বা উপাদান মিলিয়ে নতুন কিছু তৈরি করা", "Students synthesize ideas from two books.", "শিক্ষার্থীরা দুটি বইয়ের ধারণা একত্র করে।"),
    _vocab("Group 12", 6, "Auditory", "Adjective", "Related to hearing or the sense of sound.", "শোনা বা শ্রবণেন্দ্রিয়-সংক্রান্ত", "The test checks auditory skills.", "পরীক্ষাটি শ্রবণ দক্ষতা যাচাই করে।"),
    _vocab("Group 12", 7, "Depiction", "Noun", "A picture, description, or representation of something.", "কোনো কিছুর ছবি, বর্ণনা বা উপস্থাপন", "The painting is a depiction of village life.", "চিত্রটি গ্রামের জীবনের একটি উপস্থাপন।"),
    _vocab("Group 12", 8, "Demise", "Noun", "The end, failure, or death of someone or something.", "কোনো ব্যক্তি বা কিছুর শেষ, পতন বা মৃত্যু", "The company faced its demise.", "কোম্পানিটি তার পতনের মুখোমুখি হয়েছিল।"),
    _vocab("Group 12", 9, "Succumb", "Verb", "To stop resisting and give in to pressure, illness, or difficulty.", "চাপ, অসুস্থতা বা সমস্যার কাছে হার মানা", "Do not succumb to fear.", "ভয়ের কাছে হার মেনো না।"),
    _vocab("Group 12", 10, "Flawed", "Adjective", "Having a fault, weakness, or mistake.", "ত্রুটি, দুর্বলতা বা ভুল আছে এমন", "The plan is flawed.", "পরিকল্পনাটিতে ত্রুটি আছে।"),
    _vocab("Group 12", 11, "Clipper", "Noun", "A fast sailing ship, or a tool used for cutting.", "দ্রুতগামী পালতোলা জাহাজ বা কাটার যন্ত্র", "The old clipper sailed across the sea.", "পুরোনো দ্রুতগামী জাহাজটি সমুদ্র পাড়ি দিল।"),
    _vocab("Group 12", 12, "Daunting", "Adjective", "Seeming difficult or frightening to do.", "করা কঠিন বা ভয়ংকর মনে হয় এমন", "The long climb looks daunting.", "দীর্ঘ ওঠার পথটি কঠিন মনে হচ্ছে।"),
    _vocab("Group 12", 13, "Degradation", "Noun", "The process of becoming worse or being damaged.", "খারাপ হয়ে যাওয়া বা ক্ষতিগ্রস্ত হওয়ার প্রক্রিয়া", "Pollution causes land degradation.", "দূষণ জমির ক্ষয় ঘটায়।"),
    _vocab("Group 12", 14, "Indiscriminate", "Adjective", "Done without careful choice or distinction.", "বাছবিচার বা পার্থক্য না করে করা", "Indiscriminate cutting harms forests.", "বাছবিচারহীন গাছ কাটা বনকে ক্ষতি করে।"),
    _vocab("Group 12", 15, "Unspoilt", "Adjective", "Still natural, clean, and not damaged.", "এখনো প্রাকৃতিক, পরিচ্ছন্ন ও অক্ষত", "The beach is quiet and unspoilt.", "সমুদ্রসৈকতটি শান্ত ও অক্ষত।"),
    _vocab("Group 12", 16, "Reconcile", "Verb", "To restore a friendly relationship or make two ideas agree.", "বন্ধুত্বপূর্ণ সম্পর্ক ফিরিয়ে আনা বা দুটি ধারণার মিল ঘটানো", "The two friends tried to reconcile.", "দুই বন্ধু আবার মিল করার চেষ্টা করল।"),
    _vocab("Group 12", 17, "Metaphysics", "Noun", "The branch of philosophy that studies reality, existence, and being.", "বাস্তবতা, অস্তিত্ব ও সত্তা নিয়ে দর্শনের শাখা", "Metaphysics asks questions about existence.", "অধিবিদ্যা অস্তিত্ব সম্পর্কে প্রশ্ন করে।"),
    _vocab("Group 12", 18, "Outmode", "Verb", "To make something old-fashioned or no longer useful.", "কোনো কিছুকে সেকেলে বা আর ব্যবহারযোগ্য না করা", "New technology can outmode old machines.", "নতুন প্রযুক্তি পুরোনো যন্ত্রকে সেকেলে করে দিতে পারে।"),
    _vocab("Group 12", 19, "Panopticon", "Noun", "A prison design in which one guard can observe many prisoners from a central point.", "এমন কারাগারের নকশা যেখানে কেন্দ্র থেকে একজন প্রহরী অনেক বন্দিকে দেখতে পারে", "The prison was built as a panopticon.", "কারাগারটি প্যানঅপ্টিকন নকশায় নির্মিত হয়েছিল।"),
    _vocab("Group 12", 20, "Pedigree", "Noun", "The recorded family history or ancestry of a person or animal.", "কোনো ব্যক্তি বা প্রাণীর নথিভুক্ত বংশপরিচয়", "The dog has an impressive pedigree.", "কুকুরটির বংশধারা অত্যন্ত চমৎকার/সমৃদ্ধ।"),
    _vocab("Group 13", 1, "Gallant", "Adjective", "Brave, noble, and polite.", "সাহসী, মহৎ ও ভদ্র", "The gallant man helped the child.", "সাহসী লোকটি শিশুটিকে সাহায্য করল।"),
    _vocab("Group 13", 2, "Enchanting", "Adjective", "Very beautiful, pleasant, or charming.", "খুব সুন্দর, মনোরম বা মোহনীয়", "The garden is enchanting.", "বাগানটি মোহনীয়।"),
    _vocab("Group 13", 3, "Repercussion", "Noun", "A bad or unexpected result of an action.", "কোনো কাজের খারাপ বা অপ্রত্যাশিত ফল", "The mistake had a serious repercussion.", "ভুলটির একটি গুরুতর পরিণতি ছিল।"),
    _vocab("Group 13", 4, "Pretence", "Noun", "An act of making something seem true when it is not.", "সত্য নয় এমন কিছুকে সত্য বলে দেখানোর ভান", "He smiled under the pretence of being happy.", "সে সুখী হওয়ার ভান করে হাসল।"),
    _vocab("Group 13", 5, "Scarce", "Adjective", "Not easy to find or not available in large amounts.", "সহজে পাওয়া যায় না বা অল্প পরিমাণে আছে এমন", "Clean water is scarce here.", "এখানে পরিষ্কার পানি খুব কম।"),
    _vocab("Group 13", 6, "Spontaneous", "Adjective", "Done naturally and suddenly without planning.", "পরিকল্পনা ছাড়া স্বাভাবিকভাবে ও হঠাৎ করা", "Her spontaneous smile made us happy.", "তার স্বতঃস্ফূর্ত হাসি আমাদের খুশি করল।"),
    _vocab("Group 13", 7, "Intervene", "Verb", "To become involved in order to help or stop a problem.", "সাহায্য করতে বা সমস্যা থামাতে মাঝখানে জড়িত হওয়া", "The teacher intervened in the fight.", "শিক্ষক ঝগড়ায় হস্তক্ষেপ করলেন।"),
    _vocab("Group 13", 8, "Consumerism", "Noun", "The habit of buying and using many goods.", "অনেক পণ্য কেনা ও ব্যবহারের প্রবণতা", "Consumerism encourages people to buy more.", "ভোগবাদ মানুষকে বেশি কিনতে উৎসাহিত করে।"),
    _vocab("Group 13", 9, "Elaborate", "Adjective / Verb", "Having many details; to explain or develop in detail.", "অনেক বিস্তারিতযুক্ত; বিস্তারিতভাবে ব্যাখ্যা করা", "The palace has an elaborate design.", "প্রাসাদটির নকশা খুব বিস্তারিত।"),
    _vocab("Group 13", 10, "Municipality", "Noun", "A town or city with its own local government.", "নিজস্ব স্থানীয় সরকারসহ শহর বা নগর এলাকা", "The municipality repaired the road.", "পৌরসভা রাস্তাটি মেরামত করেছে।"),
    _vocab("Group 13", 11, "Unanimously", "Adverb", "With everyone agreeing.", "সবার সম্মতিতে", "The team unanimously chose Ali.", "দলটি সর্বসম্মতভাবে আলীকে বেছে নিল।"),
    _vocab("Group 13", 12, "Conspicuous", "Adjective", "Easy to notice or see.", "সহজে চোখে পড়ে এমন", "His red hat was conspicuous.", "তার লাল টুপিটি সহজেই চোখে পড়ছিল।"),
    _vocab("Group 13", 13, "Vandalism", "Noun", "The deliberate damage of public or private property.", "ইচ্ছাকৃতভাবে সরকারি বা ব্যক্তিগত সম্পত্তি নষ্ট করা", "The wall was damaged by vandalism.", "ভাঙচুরের কারণে দেয়ালটি ক্ষতিগ্রস্ত হয়েছিল।"),
    _vocab("Group 13", 14, "Succinctly", "Adverb", "In a brief and clear way.", "সংক্ষিপ্ত ও পরিষ্কারভাবে", "She explained the idea succinctly.", "সে ধারণাটি সংক্ষেপে ও পরিষ্কারভাবে ব্যাখ্যা করল।"),
    _vocab("Group 13", 15, "Inherently", "Adverb", "In a natural or essential way.", "স্বাভাবিক বা মৌলিকভাবে", "Fire is inherently dangerous.", "আগুন স্বভাবগতভাবে বিপজ্জনক।"),
    _vocab("Group 13", 16, "Predisposition", "Noun", "A natural tendency to develop a condition or behave in a way.", "কোনো অবস্থা তৈরি হওয়া বা বিশেষভাবে আচরণের স্বাভাবিক প্রবণতা", "He has a predisposition to allergies.", "তার অ্যালার্জি হওয়ার প্রবণতা আছে।"),
    _vocab("Group 13", 17, "Dichotomy", "Noun", "A division into two very different parts.", "দুটি খুব ভিন্ন অংশে বিভাজন", "The book shows a dichotomy between rich and poor.", "বইটি ধনী ও গরিবের মধ্যে বিভাজন দেখায়।"),
    _vocab("Group 13", 18, "Extrinsic", "Adjective", "Coming from outside rather than from within.", "ভেতর থেকে নয়, বাইরে থেকে আসা", "Money is an extrinsic reward.", "অর্থ একটি বাহ্যিক পুরস্কার।"),
    _vocab("Group 13", 19, "Turnover", "Noun", "The amount of business done, or the rate at which workers leave.", "ব্যবসার মোট পরিমাণ বা কর্মী চলে যাওয়ার হার", "The shop has a high turnover.", "দোকানটির বিক্রির পরিমাণ বেশি।"),
    _vocab("Group 13", 20, "Apprenticeship", "Noun", "A period of learning a job from a skilled worker.", "দক্ষ কর্মীর কাছ থেকে কাজ শেখার সময়কাল", "He began an apprenticeship as a mechanic.", "সে মেকানিক হিসেবে শিক্ষানবিশি শুরু করল।"),
    _vocab("Group 14", 1, "Excursion", "Noun", "A short journey made for pleasure or learning.", "আনন্দ বা শিক্ষার জন্য ছোট ভ্রমণ", "Our class went on an excursion.", "আমাদের শ্রেণি একটি শিক্ষা সফরে গিয়েছিল।"),
    _vocab("Group 14", 2, "Occidental", "Adjective / Noun", "Related to the Western world.", "পাশ্চাত্য জগতের সঙ্গে সম্পর্কিত", "The museum has Occidental art.", "জাদুঘরটিতে পাশ্চাত্য শিল্প আছে।"),
    _vocab("Group 14", 3, "Culmination", "Noun", "The final and most important point of an activity.", "কোনো কাজের চূড়ান্ত ও সবচেয়ে গুরুত্বপূর্ণ পর্যায়", "The concert was the culmination of the festival.", "কনসার্টটি উৎসবের চূড়ান্ত অনুষ্ঠান ছিল।"),
    _vocab("Group 14", 4, "Ventilation", "Noun", "The movement of fresh air through a room or building.", "ঘর বা ভবনে তাজা বাতাস চলাচলের ব্যবস্থা", "This room needs better ventilation.", "এই ঘরে আরও ভালো বায়ু চলাচল দরকার।"),
    _vocab("Group 14", 5, "Relentlessly", "Adverb", "Without stopping or becoming less strong.", "না থেমে বা শক্তি না কমিয়ে", "The rain fell relentlessly.", "বৃষ্টি বিরামহীনভাবে পড়ল।"),
    _vocab("Group 14", 6, "Ingeniously", "Adverb", "In a very clever and original way.", "খুব বুদ্ধিদীপ্ত ও মৌলিকভাবে", "She ingeniously fixed the broken chair.", "সে বুদ্ধি করে ভাঙা চেয়ারটি ঠিক করল।"),
    _vocab("Group 14", 7, "Communal", "Adjective", "Shared by all members of a group.", "একটি দলের সবার যৌথ ব্যবহারের", "We eat in a communal kitchen.", "আমরা একটি যৌথ রান্নাঘরে খাই।"),
    _vocab("Group 14", 8, "Contend", "Verb", "To argue that something is true; to compete.", "কিছু সত্য বলে যুক্তি দেওয়া; প্রতিযোগিতা করা", "Experts contend that the plan will work.", "বিশেষজ্ঞরা বলেন যে পরিকল্পনাটি কাজ করবে।"),
    _vocab("Group 14", 9, "Clamour", "Verb / Noun", "To demand something loudly; a loud noise or demand.", "জোরে কিছু দাবি করা; উচ্চ শব্দ বা দাবি", "The children clamour for food.", "শিশুরা খাবারের জন্য জোরে দাবি করে।"),
    _vocab("Group 14", 10, "Rhetoric", "Noun", "Language used to persuade or impress people.", "মানুষকে প্রভাবিত বা রাজি করানোর ভাষা", "The speech was full of political rhetoric.", "ভাষণটি রাজনৈতিক কথাবার্তায় পূর্ণ ছিল।"),
    _vocab("Group 14", 11, "Ironically", "Adverb", "In a way that is opposite to what is expected.", "প্রত্যাশার বিপরীতভাবে", "Ironically, the fire station caught fire.", "পরিহাসের বিষয়, দমকলকেন্দ্রেই আগুন লেগেছিল।"),
    _vocab("Group 14", 12, "Detrimental", "Adjective", "Causing harm or damage.", "ক্ষতি বা ক্ষয় সৃষ্টি করে এমন", "Smoking is detrimental to health.", "ধূমপান স্বাস্থ্যের জন্য ক্ষতিকর।"),
    _vocab("Group 14", 13, "Outweigh", "Verb", "To be greater or more important than something else.", "অন্য কিছুর চেয়ে বেশি বা গুরুত্বপূর্ণ হওয়া", "The benefits outweigh the risks.", "সুবিধাগুলো ঝুঁকির চেয়ে বেশি।"),
    _vocab("Group 14", 14, "Devoid of", "Adjective Phrase", "Completely lacking something.", "সম্পূর্ণভাবে কোনো কিছুহীন", "The room was devoid of furniture.", "ঘরটিতে কোনো আসবাব ছিল না।"),
    _vocab("Group 14", 15, "Hierarchy", "Noun", "A system in which people or things are ranked by importance.", "গুরুত্ব অনুযায়ী মানুষ বা জিনিসের স্তরভিত্তিক ব্যবস্থা", "The company has a clear hierarchy.", "কোম্পানিটির একটি পরিষ্কার পদক্রম আছে।"),
    _vocab("Group 14", 16, "Scrap", "Verb / Noun", "To throw away or stop using something; waste material.", "কিছু ফেলে দেওয়া বা ব্যবহার বন্ধ করা; বর্জ্য উপাদান", "They will scrap the old machine.", "তারা পুরোনো যন্ত্রটি বাতিল করবে।"),
    _vocab("Group 14", 17, "Bandwagon", "Noun", "A popular activity or idea that many people join.", "জনপ্রিয় কাজ বা ধারণা যাতে অনেক মানুষ যোগ দেয়", "Many companies joined the green bandwagon.", "অনেক কোম্পানি পরিবেশবান্ধব ধারায় যোগ দিল।"),
    _vocab("Group 14", 18, "Implicit", "Adjective", "Suggested or understood without being stated directly.", "সরাসরি বলা না হলেও বোঝানো বা উপলব্ধ", "His message had an implicit warning.", "তার বার্তায় একটি পরোক্ষ সতর্কতা ছিল।"),
    _vocab("Group 14", 19, "Conceptualize", "Verb", "To form a clear idea of something.", "কোনো কিছুর পরিষ্কার ধারণা তৈরি করা", "It is hard to conceptualize the future.", "ভবিষ্যৎ সম্পর্কে পরিষ্কার ধারণা করা কঠিন।"),
    _vocab("Group 14", 20, "Elucidate", "Verb", "To explain something and make it clear.", "কিছু ব্যাখ্যা করে পরিষ্কার করা", "The teacher elucidated the rule.", "শিক্ষক নিয়মটি পরিষ্কার করে ব্যাখ্যা করলেন।"),
    _vocab("Group 15", 1, "Statesmen", "Plural Noun", "Experienced and respected political leaders.", "অভিজ্ঞ ও সম্মানিত রাজনৈতিক নেতারা", "The statesmen discussed peace.", "রাষ্ট্রনায়কেরা শান্তি নিয়ে আলোচনা করলেন।"),
    _vocab("Group 15", 2, "Platonic", "Adjective", "Friendly and loving but not romantic.", "বন্ধুত্বপূর্ণ ও স্নেহপূর্ণ, কিন্তু রোমান্টিক নয়", "They have a platonic friendship.", "তাদের বন্ধুত্বটি রোমান্টিক নয়।"),
    _vocab("Group 15", 3, "Emergence", "Noun", "The process of appearing or becoming known.", "প্রকাশ পাওয়া বা পরিচিত হওয়ার প্রক্রিয়া", "The emergence of new technology changed work.", "নতুন প্রযুক্তির আবির্ভাব কাজকে বদলে দিয়েছে।"),
    _vocab("Group 15", 4, "Competencies", "Plural Noun", "Skills and abilities needed to do something well.", "কোনো কাজ ভালোভাবে করার দক্ষতা ও সামর্থ্যগুলো", "The job requires several competencies.", "কাজটির জন্য কয়েকটি দক্ষতা দরকার।"),
    _vocab("Group 15", 5, "Presuppositions", "Plural Noun", "Ideas believed to be true before discussion or proof.", "আলোচনা বা প্রমাণের আগেই সত্য বলে ধরে নেওয়া ধারণাগুলো", "The argument has false presuppositions.", "যুক্তিটিতে ভুল পূর্বধারণা আছে।"),
    _vocab("Group 15", 6, "Millipedes", "Plural Noun", "Small animals with long bodies and many legs.", "লম্বা শরীর ও অনেক পাযুক্ত ছোট প্রাণীগুলো", "Millipedes live under wet leaves.", "মিলিপিডগুলো ভেজা পাতার নিচে থাকে।"),
    _vocab("Group 15", 7, "Noxious", "Adjective", "Harmful, poisonous, or very unpleasant.", "ক্ষতিকর, বিষাক্ত বা খুব অপ্রীতিকর", "The factory released noxious gas.", "কারখানাটি ক্ষতিকর গ্যাস ছেড়েছে।"),
    _vocab("Group 15", 8, "Extractions", "Plural Noun", "Acts of removing or taking something out.", "কোনো কিছু বের বা সরিয়ে নেওয়ার কাজগুলো", "The dentist performed two tooth extractions.", "দাঁতের ডাক্তার দুটি দাঁত তুলেছেন।"),
    _vocab("Group 15", 9, "Looming", "Adjective", "Appearing large, close, and possibly threatening.", "বড়, কাছাকাছি ও সম্ভবত ভীতিকরভাবে সামনে আসছে এমন", "A storm was looming over the town.", "শহরের ওপর একটি ঝড় ঘনিয়ে আসছিল।"),
    _vocab("Group 15", 10, "Terrestrial", "Adjective", "Related to Earth or living on land.", "পৃথিবী বা স্থলে বসবাসের সঙ্গে সম্পর্কিত", "Elephants are terrestrial animals.", "হাতি স্থলজ প্রাণী।"),
    _vocab("Group 15", 11, "Bewildering", "Adjective", "Very confusing and difficult to understand.", "খুব বিভ্রান্তিকর ও বোঝা কঠিন", "The map was bewildering.", "মানচিত্রটি খুব বিভ্রান্তিকর ছিল।"),
    _vocab("Group 15", 12, "Daunt", "Verb", "To make someone feel afraid or less confident.", "কাউকে ভীত বা কম আত্মবিশ্বাসী করা", "The difficult task did not daunt her.", "কঠিন কাজটি তাকে ভয় পাইয়ে দেয়নি।"),
    _vocab("Group 15", 13, "Ubiquity", "Noun", "The state of being present everywhere.", "সর্বত্র উপস্থিত থাকার অবস্থা", "The ubiquity of phones is clear.", "ফোনের সর্বব্যাপী উপস্থিতি স্পষ্ট।"),
    _vocab("Group 15", 14, "Captivity", "Noun", "The state of being kept as a prisoner or confined.", "বন্দি বা আবদ্ধ অবস্থায় থাকা", "The bird lived in captivity.", "পাখিটি বন্দি অবস্থায় বাস করত।"),
    _vocab("Group 15", 15, "Subdue", "Verb", "To bring someone or something under control.", "কাউকে বা কিছুকে নিয়ন্ত্রণে আনা", "The police subdued the angry man.", "পুলিশ রাগান্বিত লোকটিকে নিয়ন্ত্রণে আনল।"),
    _vocab("Group 15", 16, "Pathogenic", "Adjective", "Able to cause disease.", "রোগ সৃষ্টি করতে সক্ষম", "Some bacteria are pathogenic.", "কিছু ব্যাকটেরিয়া রোগ সৃষ্টি করে।"),
    _vocab("Group 15", 17, "Precedent", "Noun", "An earlier event or decision used as an example later.", "পরবর্তীতে উদাহরণ হিসেবে ব্যবহৃত আগের ঘটনা বা সিদ্ধান্ত", "The court decision set a precedent.", "আদালতের সিদ্ধান্তটি একটি নজির স্থাপন করল।"),
    _vocab("Group 15", 18, "Deprive", "Verb", "To prevent someone from having something important.", "কাউকে গুরুত্বপূর্ণ কিছু থেকে বঞ্চিত করা", "Do not deprive children of sleep.", "শিশুদের ঘুম থেকে বঞ্চিত করো না।"),
    _vocab("Group 15", 19, "Expound", "Verb", "To explain an idea in detail.", "কোনো ধারণা বিস্তারিতভাবে ব্যাখ্যা করা", "The teacher expounded the theory.", "শিক্ষক তত্ত্বটি বিস্তারিতভাবে ব্যাখ্যা করলেন।"),
    _vocab("Group 15", 20, "Repertoire", "Noun", "The complete set of skills, songs, or works a person can perform.", "কোনো ব্যক্তির সব দক্ষতা, গান বা পরিবেশনযোগ্য কাজের সংগ্রহ", "The singer has a large repertoire.", "গায়কের অনেক গানের সংগ্রহ আছে।"),
    _vocab("Group 16", 1, "Consensus", "Noun", "General agreement among a group of people.", "একদল মানুষের সাধারণ সম্মতি", "The group reached a consensus.", "দলটি একটি সাধারণ সিদ্ধান্তে পৌঁছাল।"),
    _vocab("Group 16", 2, "Intrinsic", "Adjective", "Belonging naturally to something and being essential.", "স্বাভাবিকভাবে কোনো কিছুর নিজস্ব ও অপরিহার্য", "Honesty has intrinsic value.", "সততার নিজস্ব মূল্য আছে।"),
    _vocab("Group 16", 3, "Dispositional", "Adjective", "Related to a person's usual character or behaviour.", "কোনো ব্যক্তির স্বাভাবিক চরিত্র বা আচরণের সঙ্গে সম্পর্কিত", "Patience is a dispositional trait.", "ধৈর্য একটি স্বভাবগত বৈশিষ্ট্য।"),
    _vocab("Group 16", 4, "Extrinsically", "Adverb", "Because of outside rewards or influences.", "বাইরের পুরস্কার বা প্রভাবের কারণে", "He was extrinsically motivated by money.", "সে অর্থের কারণে বাহ্যিকভাবে অনুপ্রাণিত ছিল।"),
    _vocab("Group 16", 5, "Autonomy", "Noun", "The freedom to make one's own decisions.", "নিজের সিদ্ধান্ত নেওয়ার স্বাধীনতা", "The workers want more autonomy.", "কর্মীরা আরও স্বাধীনতা চায়।"),
    _vocab("Group 16", 6, "Predominantly", "Adverb", "Mainly or mostly.", "প্রধানত বা বেশিরভাগ ক্ষেত্রে", "The area is predominantly rural.", "এলাকাটি প্রধানত গ্রামীণ।"),
    _vocab("Group 16", 7, "Deteriorate", "Verb", "To become worse in quality or condition.", "মান বা অবস্থায় খারাপ হওয়া", "The road may deteriorate in heavy rain.", "ভারী বৃষ্টিতে রাস্তাটি খারাপ হতে পারে।"),
    _vocab("Group 16", 8, "Senescence", "Noun", "The process of becoming old.", "বৃদ্ধ হওয়ার প্রক্রিয়া", "Senescence affects all living things.", "বার্ধক্য সব জীবিত প্রাণীকে প্রভাবিত করে।"),
    _vocab("Group 16", 9, "Entomologist", "Noun", "A scientist who studies insects.", "পোকামাকড় নিয়ে গবেষণাকারী বিজ্ঞানী", "The entomologist studies bees.", "কীটতত্ত্ববিদ মৌমাছি নিয়ে গবেষণা করেন।"),
    _vocab("Group 16", 10, "Ostracism", "Noun", "The act of excluding someone from a group.", "কাউকে দল থেকে বাদ দেওয়ার কাজ", "Ostracism made the boy feel lonely.", "সামাজিক বর্জন ছেলেটিকে একা অনুভব করিয়েছিল।"),
    _vocab("Group 16", 11, "Parasites", "Plural Noun", "Organisms that live on or in another organism and take food from it.", "অন্য জীবের শরীরে বা ওপর বসবাস করে খাদ্য নেয় এমন জীবগুলো", "Some parasites live inside animals.", "কিছু পরজীবী প্রাণীর শরীরের ভেতরে থাকে।"),
    _vocab("Group 16", 12, "Reservoir", "Noun", "A place where water or another substance is stored.", "পানি বা অন্য পদার্থ সংরক্ষণের স্থান", "The reservoir supplies water to the city.", "জলাধারটি শহরে পানি সরবরাহ করে।"),
    _vocab("Group 16", 13, "Outreach", "Noun", "Work that provides help or services to people in a community.", "সম্প্রদায়ের মানুষকে সাহায্য বা সেবা দেওয়ার কার্যক্রম", "The school runs an outreach programme.", "স্কুলটি একটি জনসেবা কার্যক্রম চালায়।"),
    _vocab("Group 16", 14, "Dismal", "Adjective", "Very bad, sad, or without hope.", "খুব খারাপ, দুঃখজনক বা আশাহীন", "The weather was cold and dismal.", "আবহাওয়া ঠান্ডা ও বিষণ্ন ছিল।"),
    _vocab("Group 16", 15, "Debris", "Noun", "Broken pieces left after damage or destruction.", "ক্ষতি বা ধ্বংসের পর পড়ে থাকা ভাঙা টুকরো", "The road was covered with debris.", "রাস্তাটি ধ্বংসাবশেষে ঢাকা ছিল।"),
    _vocab("Group 16", 16, "Conjure", "Verb", "To make an image or idea appear in the mind.", "মনে কোনো ছবি বা ধারণা তৈরি করা", "The story can conjure images of the sea.", "গল্পটি মনে সমুদ্রের ছবি তৈরি করতে পারে।"),
    _vocab("Group 16", 17, "Misperceptions", "Plural Noun", "Wrong ideas or understandings about something.", "কোনো বিষয়ে ভুল ধারণা বা বোঝাপড়াগুলো", "The lesson corrected our misperceptions.", "পাঠটি আমাদের ভুল ধারণাগুলো সংশোধন করেছে।"),
    _vocab("Group 16", 18, "Strandings", "Plural Noun", "Events in which animals or boats become stuck on land or in shallow water.", "প্রাণী বা নৌযান স্থল বা অগভীর পানিতে আটকে যাওয়ার ঘটনাগুলো", "Whale strandings sometimes happen here.", "এখানে কখনো কখনো তিমি তীরে আটকে যায়।"),
    _vocab("Group 16", 19, "Entanglement", "Noun", "The state of being caught or twisted in something.", "কোনো কিছুর মধ্যে আটকে বা জড়িয়ে যাওয়ার অবস্থা", "The bird escaped from entanglement in the net.", "পাখিটি জালে আটকে পড়া থেকে মুক্তি পেল।"),
    _vocab("Group 16", 20, "Interrogate", "Verb", "To ask someone many questions, often officially.", "কাউকে অনেক প্রশ্ন করা, প্রায়ই আনুষ্ঠানিকভাবে", "The police will interrogate the suspect.", "পুলিশ সন্দেহভাজন ব্যক্তিকে জিজ্ঞাসাবাদ করবে।"),
    _vocab("Group 17", 1, "Foliage", "Noun", "The leaves of a plant or tree.", "গাছ বা উদ্ভিদের পাতাসমূহ", "The tree has thick green foliage.", "গাছটিতে ঘন সবুজ পাতা আছে।"),
    _vocab("Group 17", 2, "Encase", "Verb", "To completely cover or surround something.", "কোনো কিছুকে সম্পূর্ণভাবে ঢেকে বা ঘিরে রাখা", "The seed is encased in a red cover.", "বীজটি একটি লাল আবরণে ঢাকা।"),
    _vocab("Group 17", 3, "Crimson", "Adjective / Noun", "A deep red colour.", "গাঢ় লাল রং", "She wore a crimson dress.", "সে একটি গাঢ় লাল পোশাক পরেছিল।"),
    _vocab("Group 17", 4, "Aril", "Noun", "A soft or fleshy covering around some seeds.", "কিছু বীজের চারপাশের নরম বা রসালো আবরণ", "The seed has a red aril.", "বীজটির একটি লাল রসালো আবরণ আছে।"),
    _vocab("Group 17", 5, "Dominance", "Noun", "The state of having more power or control than others.", "অন্যদের চেয়ে বেশি ক্ষমতা বা নিয়ন্ত্রণ থাকার অবস্থা", "The large company gained market dominance.", "বড় কোম্পানিটি বাজারে আধিপত্য অর্জন করেছে।"),
    _vocab("Group 17", 6, "Subcontract", "Verb", "To pay another person or company to do part of a job.", "কাজের একটি অংশ করার জন্য অন্য ব্যক্তি বা প্রতিষ্ঠানকে দায়িত্ব দেওয়া", "The company will subcontract the painting work.", "কোম্পানিটি রং করার কাজ অন্য প্রতিষ্ঠানকে দেবে।"),
    _vocab("Group 17", 7, "Uproot", "Verb", "To pull a plant and its roots out of the ground.", "শিকড়সহ গাছ মাটি থেকে তুলে ফেলা", "The storm can uproot small trees.", "ঝড় ছোট গাছ শিকড়সহ তুলে ফেলতে পারে।"),
    _vocab("Group 17", 8, "Transplant", "Verb / Noun", "To move a plant or organ to another place.", "গাছ বা অঙ্গ এক স্থান থেকে অন্য স্থানে স্থানান্তর করা", "We will transplant the young tree.", "আমরা ছোট গাছটি অন্য জায়গায় লাগাব।"),
    _vocab("Group 17", 9, "Incidence", "Noun", "The number or rate of times something happens.", "কোনো ঘটনা কতবার ঘটে তার সংখ্যা বা হার", "The incidence of illness is low here.", "এখানে অসুস্থতার হার কম।"),
    _vocab("Group 17", 10, "Autonomy", "Noun", "The freedom to make one's own decisions.", "নিজের সিদ্ধান্ত নেওয়ার স্বাধীনতা", "The team has autonomy in its work.", "দলটির কাজে সিদ্ধান্ত নেওয়ার স্বাধীনতা আছে।"),
    _vocab("Group 17", 11, "Regulatory", "Adjective", "Related to rules or the control of an activity.", "নিয়ম বা কোনো কার্যক্রম নিয়ন্ত্রণের সঙ্গে সম্পর্কিত", "The agency has a regulatory role.", "সংস্থাটির একটি নিয়ন্ত্রণমূলক ভূমিকা আছে।"),
    _vocab("Group 17", 12, "Telepresence", "Noun", "Technology that makes a person seem present in another place.", "প্রযুক্তির মাধ্যমে দূরের স্থানে উপস্থিত থাকার অনুভূতি", "Telepresence lets the doctor speak to the patient from far away.", "টেলিপ্রেজেন্সের মাধ্যমে ডাক্তার দূর থেকে রোগীর সঙ্গে কথা বলতে পারেন।"),
    _vocab("Group 17", 13, "Wildebeest", "Noun", "A large African animal related to cattle.", "গরু-জাতীয় একটি বড় আফ্রিকান প্রাণী", "A wildebeest runs across the grassland.", "একটি উইল্ডবিস্ট তৃণভূমির ওপর দিয়ে দৌড়ায়।"),
    _vocab("Group 17", 14, "Nomadic", "Adjective", "Moving from place to place instead of living permanently in one place.", "স্থায়ীভাবে এক জায়গায় না থেকে স্থান থেকে স্থানে ঘুরে বেড়ায় এমন", "The family lives a nomadic life.", "পরিবারটি যাযাবর জীবনযাপন করে।"),
    _vocab("Group 17", 15, "Laboriously", "Adverb", "With a lot of time, effort, and difficulty.", "অনেক সময়, পরিশ্রম ও কষ্টের সঙ্গে", "He laboriously carried the heavy box.", "সে অনেক কষ্টে ভারী বাক্সটি বহন করল।"),
    _vocab("Group 17", 16, "Mountaineer", "Noun", "A person who climbs mountains.", "পাহাড়ে আরোহণকারী ব্যক্তি", "The mountaineer climbed the high peak.", "পর্বতারোহী উঁচু চূড়ায় উঠলেন।"),
    _vocab("Group 17", 17, "Quantitative", "Adjective", "Related to amounts or numbers.", "পরিমাণ বা সংখ্যার সঙ্গে সম্পর্কিত", "The report uses quantitative data.", "প্রতিবেদনটি সংখ্যাভিত্তিক তথ্য ব্যবহার করে।"),
    _vocab("Group 17", 18, "Choreographers", "Plural Noun", "People who create and arrange dance movements.", "নাচের ভঙ্গি ও চলন তৈরি ও সাজান এমন ব্যক্তিরা", "The choreographers planned the dance.", "নৃত্যপরিচালকেরা নাচটি পরিকল্পনা করলেন।"),
    _vocab("Group 17", 19, "Urbanist", "Noun", "A person who studies or plans cities.", "শহর নিয়ে গবেষণা বা পরিকল্পনা করেন এমন ব্যক্তি", "The urbanist designed a safer street.", "নগরপরিকল্পনাবিদ একটি নিরাপদ রাস্তার নকশা করলেন।"),
    _vocab("Group 17", 20, "Sociologist", "Noun", "A person who studies society and social behaviour.", "সমাজ ও সামাজিক আচরণ নিয়ে গবেষণাকারী ব্যক্তি", "The sociologist studies family life.", "সমাজবিজ্ঞানী পারিবারিক জীবন নিয়ে গবেষণা করেন।"),
    _vocab("Group 18", 1, "Improvise", "Verb", "To create or do something without planning it first.", "আগে পরিকল্পনা না করে কিছু তৈরি বা করা", "We had no table, so we improvised one from boxes.", "আমাদের টেবিল ছিল না, তাই বাক্স দিয়ে একটি বানালাম।"),
    _vocab("Group 18", 2, "Counter-intuitive", "Adjective", "Opposite to what seems naturally correct or expected.", "স্বাভাবিকভাবে সঠিক বা প্রত্যাশিত মনে হয় তার বিপরীত", "The answer seems counter-intuitive.", "উত্তরটি স্বাভাবিক ধারণার বিপরীত মনে হয়।"),
    _vocab("Group 18", 3, "Carriageway", "Noun", "The part of a road used by vehicles.", "যানবাহন চলাচলের জন্য রাস্তার অংশ", "Do not walk on the carriageway.", "যানবাহন চলার রাস্তায় হাঁটবে না।"),
    _vocab("Group 18", 4, "Choreography", "Noun", "The art or arrangement of dance movements.", "নাচের ভঙ্গি ও চলন সাজানোর শিল্প", "The choreography was simple and beautiful.", "নাচের বিন্যাসটি সহজ ও সুন্দর ছিল।"),
    _vocab("Group 18", 5, "Cognitive", "Adjective", "Related to thinking, learning, and understanding.", "চিন্তা, শেখা ও বোঝার সঙ্গে সম্পর্কিত", "Reading improves cognitive skills.", "পড়া চিন্তার দক্ষতা বাড়ায়।"),
    _vocab("Group 18", 6, "Simulate", "Verb", "To copy a real situation or process for practice or study.", "অনুশীলন বা গবেষণার জন্য বাস্তব পরিস্থিতি বা প্রক্রিয়া অনুকরণ করা", "The game simulates driving a car.", "খেলাটি গাড়ি চালানোর অনুকরণ করে।"),
    _vocab("Group 18", 7, "Expertise", "Noun", "Special knowledge or skill in a particular subject.", "কোনো বিষয়ে বিশেষ জ্ঞান বা দক্ষতা", "She has expertise in computer repair.", "কম্পিউটার মেরামতে তার বিশেষ দক্ষতা আছে।"),
    _vocab("Group 18", 8, "Aesthetic", "Adjective / Noun", "Related to beauty or the appreciation of beauty.", "সৌন্দর্য বা সৌন্দর্যবোধের সঙ্গে সম্পর্কিত", "The room has a simple aesthetic.", "ঘরটির সৌন্দর্যধারা সহজ।"),
    _vocab("Group 18", 9, "Stagger", "Verb", "To arrange people or events at different times or positions.", "মানুষ বা ঘটনা ভিন্ন সময় বা অবস্থানে সাজানো", "The school will stagger lunch times.", "স্কুলটি দুপুরের খাবারের সময়গুলো আলাদা করবে।"),
    _vocab("Group 18", 10, "Geneticist", "Noun", "A scientist who studies genes and heredity.", "জিন ও বংশগতি নিয়ে গবেষণাকারী বিজ্ঞানী", "The geneticist studies inherited diseases.", "জিনবিজ্ঞানী বংশগত রোগ নিয়ে গবেষণা করেন।"),
    _vocab("Group 18", 11, "Embryo", "Noun", "A very early stage of a developing animal or plant.", "বিকাশমান প্রাণী বা উদ্ভিদের একেবারে প্রাথমিক অবস্থা", "The embryo grows inside the egg.", "ভ্রূণটি ডিমের ভেতরে বেড়ে ওঠে।"),
    _vocab("Group 18", 12, "Pioneering", "Adjective", "Introducing new ideas or methods for the first time.", "প্রথমবার নতুন ধারণা বা পদ্ধতি চালু করে এমন", "She did pioneering research.", "তিনি অগ্রগামী গবেষণা করেছেন।"),
    _vocab("Group 18", 13, "Thylacine", "Noun", "An extinct meat-eating marsupial also called the Tasmanian tiger.", "তাসমানিয়ান টাইগার নামে পরিচিত বিলুপ্ত মাংসাশী থলিবিশিষ্ট প্রাণী", "The thylacine is now extinct.", "থাইলাসিন এখন বিলুপ্ত।"),
    _vocab("Group 18", 14, "Debilitating", "Adjective", "Making someone very weak or unable to function normally.", "কাউকে খুব দুর্বল বা স্বাভাবিক কাজ করতে অক্ষম করে এমন", "The illness was debilitating.", "অসুস্থতাটি তাকে খুব দুর্বল করে দিয়েছিল।"),
    _vocab("Group 18", 15, "Millennia", "Plural Noun", "Periods of one thousand years.", "এক হাজার বছর করে সময়কালগুলো", "People have used fire for millennia.", "মানুষ হাজার হাজার বছর ধরে আগুন ব্যবহার করেছে।"),
    _vocab("Group 18", 16, "Genomics", "Noun", "The study of all the genes in an organism.", "কোনো জীবের সব জিন নিয়ে গবেষণা", "Genomics helps scientists study diseases.", "জিনোমিক্স বিজ্ঞানীদের রোগ নিয়ে গবেষণা করতে সাহায্য করে।"),
    _vocab("Group 18", 17, "Stagnant", "Adjective", "Not moving, growing, or developing.", "নড়ছে, বাড়ছে বা উন্নত হচ্ছে না এমন", "The water in the pond is stagnant.", "পুকুরের পানি স্থির।"),
    _vocab("Group 18", 18, "Hybridise", "Verb", "To produce a hybrid by combining different species or varieties.", "ভিন্ন প্রজাতি বা জাত মিলিয়ে সংকর তৈরি করা", "Farmers hybridise plants to improve crops.", "কৃষকেরা ফসল উন্নত করতে গাছের সংকরায়ন করেন।"),
    _vocab("Group 18", 19, "Mammoth", "Noun / Adjective", "A very large extinct elephant; extremely large.", "বিলুপ্ত বিশাল হাতি; অত্যন্ত বড়", "The museum has a mammoth skeleton.", "জাদুঘরে একটি ম্যামথের কঙ্কাল আছে।"),
    _vocab("Group 18", 20, "Pinpoint", "Verb", "To find or identify the exact position or cause of something.", "কোনো কিছুর সঠিক স্থান বা কারণ নির্ধারণ করা", "The doctor tried to pinpoint the cause.", "ডাক্তার কারণটি সঠিকভাবে খুঁজে বের করার চেষ্টা করলেন।"),
    _vocab("Group 19", 1, "Tundra", "Noun", "A very cold, treeless region where the ground is often frozen.", "খুব ঠান্ডা, বৃক্ষহীন অঞ্চল যেখানে মাটি প্রায়ই জমাট থাকে", "Few trees grow in the tundra.", "টুন্ড্রায় খুব কম গাছ জন্মায়।"),
    _vocab("Group 19", 2, "Permafrost", "Noun", "Ground that remains frozen for at least two years.", "কমপক্ষে দুই বছর ধরে জমাট থাকা মাটি", "Permafrost stays frozen for many years.", "পারমাফ্রস্ট বহু বছর জমাট থাকে।"),
    _vocab("Group 19", 3, "Stimuli", "Plural Noun", "Things that cause a reaction or response.", "প্রতিক্রিয়া সৃষ্টি করে এমন বিষয়গুলো", "Bright lights are visual stimuli.", "উজ্জ্বল আলো দৃষ্টিগত উদ্দীপনা।"),
    _vocab("Group 19", 4, "Anthropologists", "Plural Noun", "Scientists who study humans, cultures, and societies.", "মানুষ, সংস্কৃতি ও সমাজ নিয়ে গবেষণাকারী বিজ্ঞানীরা", "Anthropologists study different cultures.", "নৃবিজ্ঞানীরা বিভিন্ন সংস্কৃতি নিয়ে গবেষণা করেন।"),
    _vocab("Group 19", 5, "Hierarchies", "Plural Noun", "Systems in which people or things are ranked at different levels.", "যে ব্যবস্থায় মানুষ বা জিনিস বিভিন্ন স্তরে সাজানো থাকে", "Many workplaces have clear hierarchies.", "অনেক কর্মক্ষেত্রে পরিষ্কার পদক্রম আছে।"),
    _vocab("Group 19", 6, "Submissive", "Adjective", "Willing to obey others and not resist.", "অন্যের কথা মানতে ইচ্ছুক এবং প্রতিরোধ করে না এমন", "The dog became quiet and submissive.", "কুকুরটি শান্ত ও অনুগত হয়ে গেল।"),
    _vocab("Group 19", 7, "Fraternity", "Noun", "A group of people who share a profession, interest, or brotherhood.", "একই পেশা, আগ্রহ বা ভ্রাতৃত্বে যুক্ত মানুষের দল", "The medical fraternity supported the plan.", "চিকিৎসক সমাজ পরিকল্পনাটিকে সমর্থন করেছে।"),
    _vocab("Group 19", 8, "Respite", "Noun", "A short period of rest or relief from difficulty.", "কষ্ট থেকে স্বল্প সময়ের বিশ্রাম বা স্বস্তি", "The rain gave us a respite from the heat.", "বৃষ্টি আমাদের গরম থেকে কিছুটা স্বস্তি দিল।"),
    _vocab("Group 19", 9, "Replenishment", "Noun", "The act of filling or supplying something again.", "কোনো কিছু আবার পূর্ণ করা বা সরবরাহ করার কাজ", "The lake needs regular water replenishment.", "হ্রদটিতে নিয়মিত পানি পূরণ দরকার।"),
    _vocab("Group 19", 10, "Ostensibly", "Adverb", "Apparently or according to what seems to be true.", "আপাতদৃষ্টিতে বা যা সত্য বলে মনে হয়", "He came ostensibly to help us.", "আপাতদৃষ্টিতে সে আমাদের সাহায্য করতে এসেছিল।"),
    _vocab("Group 19", 11, "Elicit", "Verb", "To cause or encourage a response or answer.", "কোনো প্রতিক্রিয়া বা উত্তর বের করে আনা", "The question may elicit a smile.", "প্রশ্নটি একটি হাসি আনতে পারে।"),
    _vocab("Group 19", 12, "Replicate", "Verb", "To copy or repeat something exactly.", "কোনো কিছু হুবহু নকল বা পুনরাবৃত্তি করা", "Scientists tried to replicate the experiment.", "বিজ্ঞানীরা পরীক্ষাটি আবার একইভাবে করার চেষ্টা করলেন।"),
    _vocab("Group 19", 13, "Sculptural", "Adjective", "Related to sculpture or shaped like a sculpture.", "ভাস্কর্য-সংক্রান্ত বা ভাস্কর্যের মতো আকৃতির", "The chair has a sculptural shape.", "চেয়ারটির আকৃতি ভাস্কর্যের মতো।"),
    _vocab("Group 19", 14, "Recline", "Verb", "To lean or lie back in a relaxed position.", "আরাম করে পেছনে হেলে বসা বা শোয়া", "You can recline the seat.", "তুমি আসনটি পেছনে হেলাতে পারো।"),
    _vocab("Group 19", 15, "Humanistic", "Adjective", "Focusing on human values, needs, and dignity.", "মানবিক মূল্যবোধ, প্রয়োজন ও মর্যাদার ওপর গুরুত্ব দেয় এমন", "The school follows a humanistic approach.", "স্কুলটি একটি মানবিক পদ্ধতি অনুসরণ করে।"),
    _vocab("Group 19", 16, "Angular", "Adjective", "Having sharp corners or angles.", "তীক্ষ্ণ কোণ বা কোনাযুক্ত", "The building has an angular shape.", "ভবনটির আকৃতি কোণযুক্ত।"),
    _vocab("Group 19", 17, "Menace", "Noun / Verb", "A person or thing that may cause harm or danger.", "ক্ষতি বা বিপদ ঘটাতে পারে এমন ব্যক্তি বা বস্তু", "The loose dog is a menace to cyclists.", "খোলা কুকুরটি সাইকেলচালকদের জন্য বিপদ।"),
    _vocab("Group 19", 18, "Desalination", "Noun", "The process of removing salt from seawater.", "সমুদ্রের পানি থেকে লবণ সরানোর প্রক্রিয়া", "Desalination makes seawater usable.", "লবণমুক্তকরণ সমুদ্রের পানি ব্যবহারযোগ্য করে।"),
    _vocab("Group 19", 19, "Microfinance", "Noun", "Small loans and financial services for people with low incomes.", "কম আয়ের মানুষের জন্য ছোট ঋণ ও আর্থিক সেবা", "Microfinance helped her start a small shop.", "ক্ষুদ্রঋণ তাকে একটি ছোট দোকান শুরু করতে সাহায্য করেছে।"),
    _vocab("Group 19", 20, "Humanitarian", "Adjective / Noun", "Concerned with helping people who are suffering.", "কষ্টে থাকা মানুষকে সাহায্য করার সঙ্গে সম্পর্কিত", "The group provides humanitarian aid.", "দলটি মানবিক সহায়তা দেয়।"),
    _vocab("Group 20", 1, "Boreholes", "Plural Noun", "Deep narrow holes drilled into the ground, often to reach water.", "মাটির গভীরে খোঁড়া সরু গর্তগুলো, সাধারণত পানি পাওয়ার জন্য", "The village uses boreholes for water.", "গ্রামটি পানির জন্য গভীর নলকূপ ব্যবহার করে।"),
